const raw = $input.item.json || {};
const body = (raw.body && typeof raw.body === "object") ? raw.body : raw;
const clean = (v, max = 1200) => String(v ?? "").replace(/[\u0000-\u001F\u007F]/g, " ").replace(/<\/?script[^>]*>/gi, "").trim().slice(0, max);
const name = clean(body.name || body.full_name || body.client_name, 120);
const email = clean(body.email, 180).toLowerCase();
const phone = clean(body.phone, 40);
const company = clean(body.company, 140) || "Unspecified";
const sourceRaw = clean(body.source, 40).toLowerCase().replace(/\s+/g, "_");
const source = sourceRaw || (raw.headers ? "webhook" : "web_form");
const inquiry_text = clean(body.inquiry_text || body.message || body.inquiry, 2000);
const requested_slot = clean(body.requested_slot, 60);
const is_webhook = Boolean(raw.headers || raw.webhookUrl);
const is_retry = Boolean(body.is_retry);
const retry_count = Number(body.retry_count || 0);
const simulate_primary_failure = Boolean(body.simulate_primary_failure);
const simulate_all_ai_failure = Boolean(body.simulate_all_ai_failure);
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const errors = [];
if (!name) errors.push("name is required");
if (!emailOk) errors.push("valid email is required");
if (!inquiry_text || inquiry_text.length < 5) errors.push("inquiry_text (>= 5 chars) is required");
const dateTag = new Date().toISOString().slice(0, 10);
const seed = email + "|" + inquiry_text.toLowerCase().slice(0, 80) + "|" + dateTag;
let hash = 2166136261;
for (let i = 0; i < seed.length; i++) { hash ^= seed.charCodeAt(i); hash = Math.imul(hash, 16777619); }
const lead_key = clean(body.lead_key, 80) || ("ZL-" + (hash >>> 0).toString(36).toUpperCase());
const nowIso = new Date().toISOString();
return {
  json: {
    is_valid: errors.length === 0,
    validation_errors: errors,
    is_webhook,
    is_retry,
    retry_count,
    simulate_primary_failure,
    simulate_all_ai_failure,
    lead_key,
    source,
    name,
    email,
    phone,
    company,
    inquiry_text,
    requested_slot,
    now_iso: nowIso
  }
};

const intake = $("Normalize & Validate Intake").first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.lead_key);
const existing = rows[0] || null;
const alreadyProcessed = Boolean(existing && !intake.is_retry && existing.status !== "RETRY_NEEDED");
return [{
  json: {
    ...intake,
    already_processed: alreadyProcessed,
    existing_status: existing ? existing.status : null,
    should_insert_raw: !existing
  },
  pairedItem: { item: 0 }
}];

const intake = $("Prepare Isolated AI Context").first().json;
let aiResult = {};
let aiProvider = "deterministic_fallback";
let recoveredFromError = false;
let queuedForRetry = false;
try {
  const p = $("Parse & Tag Primary AI").first().json;
  if (p && p.output) { aiResult = p.output; aiProvider = p.ai_provider || "gemini_pro_plus"; }
} catch {}
if (!aiResult.intent) {
  try {
    const f = $("Tag Fallback AI Output").first().json;
    if (f && f.output) { aiResult = f.output; aiProvider = f.ai_provider || "openrouter_fallback"; recoveredFromError = true; }
  } catch {}
}
if (!aiResult.intent) {
  try {
    const d = $("Deterministic Safe Fallback").first().json;
    if (d && d.output) { aiResult = d.output; aiProvider = "deterministic_fallback"; queuedForRetry = true; }
  } catch {}
}
const textLower = String(intake.inquiry_text || "").toLowerCase();
const emergencyKeywords = ["emergency", "burst", "flood", "fire", "gas leak", "lawsuit", "attorney", "legal", "data breach", "breach", "billing dispute", "chargeback", "urgent medical", "chest pain"];
const matchedFlags = emergencyKeywords.filter(k => textLower.includes(k));
let urgency = String(aiResult.urgency || "NORMAL").toUpperCase();
if (!["LOW", "NORMAL", "HIGH", "CRITICAL"].includes(urgency)) urgency = "NORMAL";
if (matchedFlags.length > 0) urgency = "CRITICAL";
const lead_score = Math.max(0, Math.min(100, Math.round(Number(aiResult.lead_score ?? 50))));
const bookings = $input.all().map(i => i.json).filter(b => b && b.booking_id && b.slot_start && b.slot_end);
let calendar_status = "NONE";
let requestedStartIso = "";
if (intake.requested_slot) {
  const dt = new Date(intake.requested_slot);
  if (!Number.isNaN(dt.getTime())) {
    requestedStartIso = dt.toISOString();
    const reqStart = dt.getTime();
    const reqEnd = reqStart + 30 * 60 * 1000;
    const hasConflict = bookings.some(b => {
      const bs = new Date(b.slot_start).getTime();
      const be = new Date(b.slot_end).getTime();
      return reqStart < be && reqEnd > bs;
    });
    calendar_status = hasConflict ? "SLOT_CONFLICT" : "SLOT_CLEAR";
  } else {
    matchedFlags.push("invalid_requested_slot");
  }
}
const randHex = () => Math.floor(Math.random() * 0xffffffff).toString(16).padStart(8, "0");
const approval_token = "tok_" + randHex() + randHex();
const status = queuedForRetry ? "MANUAL_REVIEW" : "QUEUED_FOR_APPROVAL";
const baseDecisionUrl = "https://your-n8n-instance.example.com/webhook/zero-leak/decision";
const approve_url = baseDecisionUrl + "?lead_key=" + encodeURIComponent(intake.lead_key) + "&token=" + encodeURIComponent(approval_token) + "&action=approve";
const hold_url = baseDecisionUrl + "?lead_key=" + encodeURIComponent(intake.lead_key) + "&token=" + encodeURIComponent(approval_token) + "&action=hold";
const nowIso = new Date().toISOString();
const safety_flags = matchedFlags.length ? matchedFlags.join(", ") : "none";
const draft_subject = String(aiResult.draft_subject || ("Re: Inquiry from " + intake.company)).slice(0, 180);
const draft_reply = String(aiResult.draft_reply || ("Hi " + intake.name + ", thank you for contacting us.")).slice(0, 2000);
const intent = String(aiResult.intent || "general_inquiry");
const esc = (s) => String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const email_subject = "[Approval Needed" + (urgency === "CRITICAL" ? " · CRITICAL" : "") + "] " + intake.name + " (" + intake.company + ") — Score " + lead_score + "/100";
const email_html = "<div style=\"font-family:Inter,Segoe UI,Arial,sans-serif;max-width:640px;margin:0 auto;color:#0f172a;line-height:1.5;\"><h2>Zero-Leak Executive Guardrail — Executive Review Request</h2><p><strong>Lead Key:</strong> " + esc(intake.lead_key) + " | <strong>Score:</strong> " + lead_score + "/100 | <strong>Urgency:</strong> " + esc(urgency) + "</p><p><strong>Contact:</strong> " + esc(intake.name) + " (" + esc(intake.email) + ") — " + esc(intake.company) + "</p><p><strong>AI Provider:</strong> " + esc(aiProvider) + (recoveredFromError ? " (Auto-recovered from primary failure)" : "") + "</p><p><strong>Safety Flags:</strong> " + esc(safety_flags) + " | <strong>Calendar Slot:</strong> " + esc(calendar_status) + (requestedStartIso ? " (" + esc(requestedStartIso) + ")" : "") + "</p><hr><p><strong>Inquiry:</strong><br>" + esc(intake.inquiry_text) + "</p><p><strong>Draft Reply (HELD until confirmed):</strong><br><em>Subject: " + esc(draft_subject) + "</em><br>" + esc(draft_reply) + "</p><p style=\"margin-top:20px;\"><a href=\"" + approve_url + "\" style=\"display:inline-block;padding:10px 18px;background:#10b981;color:#ffffff;text-decoration:none;border-radius:6px;font-weight:700;\">Review &amp; Approve</a> &nbsp; <a href=\"" + hold_url + "\" style=\"display:inline-block;padding:10px 18px;background:#e2e8f0;color:#0f172a;text-decoration:none;border-radius:6px;font-weight:700;\">Hold / Review</a></p></div>";
const slack_message = (urgency === "CRITICAL" ? ":rotating_light:" : ":shield:") + " *Zero-Leak Approval Needed* (" + intake.lead_key + ")\n*Lead:* " + intake.name + " (" + intake.company + ") · *Score:* " + lead_score + "/100 · *Urgency:* " + urgency + "\n*AI:* " + aiProvider + (recoveredFromError ? " (Auto-recovered)" : "") + " · *Slot:* " + calendar_status + " · *Flags:* " + safety_flags + "\n*Draft:* " + draft_reply.slice(0, 220) + "\n<" + approve_url + "|Review & Approve> | <" + hold_url + "|Hold>";
return [{
  json: {
    ...intake,
    status,
    lead_score,
    intent,
    urgency,
    ai_provider: aiProvider,
    recovered_from_error: recoveredFromError,
    queued_for_retry: queuedForRetry,
    draft_subject,
    draft_reply,
    approval_token,
    safety_flags,
    calendar_status,
    requested_slot: requestedStartIso || intake.requested_slot,
    approve_url,
    hold_url,
    email_subject,
    email_html,
    slack_message,
    now_iso: nowIso
  },
  pairedItem: { item: 0 }
}];

const raw = ($input.first() && $input.first().json) ? $input.first().json : {};
let text = typeof raw.text === 'string' ? raw.text : (typeof raw.output === 'string' ? raw.output : JSON.stringify(raw.output || raw));
text = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const firstBrace = text.indexOf('{');
const lastBrace = text.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace > firstBrace) {
  text = text.slice(firstBrace, lastBrace + 1);
}
const parsed = JSON.parse(text);
if (!parsed || typeof parsed !== 'object' || !parsed.draft_reply) {
  throw new Error('Primary Gemini JSON missing required draft_reply');
}
return [{
  json: {
    ai_provider: 'gemini_pro_plus',
    recovered_from_error: false,
    output: {
      intent: String(parsed.intent || 'general_inquiry'),
      urgency: String(parsed.urgency || 'NORMAL').toUpperCase(),
      lead_score: Number(parsed.lead_score ?? 60),
      draft_subject: String(parsed.draft_subject || 'Re: Your Inquiry'),
      draft_reply: String(parsed.draft_reply),
      reasoning: String(parsed.reasoning || '')
    }
  },
  pairedItem: { item: 0 }
}];
